function say(message){ui.status.textContent=message}
function tone(freq=440,duration=.08){try{const context=new(window.AudioContext||window.webkitAudioContext)(),osc=context.createOscillator(),gain=context.createGain();osc.type="triangle";osc.frequency.value=freq;gain.gain.setValueAtTime(.027,context.currentTime);gain.gain.exponentialRampToValueAtTime(.001,context.currentTime+duration);osc.connect(gain).connect(context.destination);osc.start();osc.stop(context.currentTime+duration);osc.onended=()=>context.close()}catch{}}
function reset(){state=createRun();started=true;selectedType=null;selectedUnit=null;targeting=false;paused=false;speed=1;phaseSeen="";shownWave=-1;ui.intro.classList.add("hidden");ui.reward.classList.add("hidden");ui.end.classList.add("hidden");say("先选择冒险者，再点击战场上的菌丝空位。");syncUI()}
function unitCard(type){const unit=UNITS[type],active=selectedType===type;return`<button class="unit-card ${active?"active":""}" data-type="${type}" ${state.phase!=="build"||state.coins<unit.cost?"disabled":""} aria-pressed="${active}"><span class="unit-portrait" style="color:${unit.color}">${ICONS[type]}</span><span class="unit-copy"><b>${unit.name}</b><small>${unit.description}</small></span><span class="unit-cost">◆ ${unit.cost}</span></button>`}
function syncInfo(){const unit=state.units.find(item=>item.id===selectedUnit);if(unit){const spec=UNITS[unit.type],cost=spec.cost+unit.level*2,covered=unit.type==="ranger"&&state.units.some(ally=>ally.type==="knight"&&Math.hypot(ally.x-unit.x,ally.y-unit.y)<=2.35);ui.info.innerHTML=`<span>${spec.name} · ${unit.level} 级</span><p>${spec.description}。${covered?"骑士掩护已激活，伤害提高 25%。":"最高可升至 3 级。"}</p><div class="unit-controls"><button id="upgradeSelected" ${state.phase!=="build"||unit.level>=3||state.coins<cost?"disabled":""}>${unit.level>=3?"已满级":`升级 ◆ ${cost}`}</button><button id="sellSelected" ${state.phase!=="build"?"disabled":""}>撤回队伍</button></div>`;$("#upgradeSelected").onclick=()=>{if(upgradeUnit(state,unit.id)){tone(610);say(`${spec.name}升至 ${unit.level} 级。`);syncUI()}};$("#sellSelected").onclick=()=>{if(sellUnit(state,unit.id)){selectedUnit=null;tone(290);say("冒险者已撤回，返还部分金币。");syncUI()}};return}const type=selectedType?UNITS[selectedType]:null;ui.info.innerHTML=type?`<span>准备部署 · ${type.name}</span><p>${type.description}。点击菌丝空位放置，部署后仍可升级或撤回。</p>`:"<span>营地告示</span><p>选择一名冒险者，再点击战场上的菌丝空位。</p>"}
function syncUI(){ui.heart.textContent=`${state.hearts} / ${state.maxHearts}`;ui.coin.textContent=state.coins;ui.waveValue.textContent=`${state.wave} / ${TOTAL_WAVES}`;ui.unitList.innerHTML=Object.keys(UNITS).map(unitCard).join("");syncInfo();ui.wave.disabled=state.phase!=="build"||!started;ui.wave.innerHTML=`${state.phase==="build"?`开始第 ${state.wave+1} 波`:state.phase==="battle"?"魔物正在进攻":state.phase==="reward"?"选择一份祝福":"战役已结束"} <span>➜</span>`;ui.spell.disabled=state.phase!=="battle"||state.spellCooldown>0||!state.enemies.length||paused;ui.spell.classList.toggle("targeting",targeting);ui.spellLabel.textContent=state.spellCooldown>0?`冷却 ${Math.ceil(state.spellCooldown)} 秒`:targeting?"点击敌群释放":"点击后选择施法位置";ui.speed.textContent=`速度 ×${speed}`;ui.pause.textContent=paused?"继续":"暂停";ui.tag.textContent=({build:"准备布阵",battle:paused?"战斗暂停":"正在守城",reward:"选择祝福",won:"守城成功",lost:"城堡陷落"})[state.phase];syncCombatAlert()}
let lastAlert="";function syncCombatAlert(){const boss=state.phase==="battle"&&state.enemies.find(e=>e.type==="boss"&&e.intent);if(!boss){ui.alert.classList.add("hidden");lastAlert="";return}const name=boss.intent.kind==="howl"?"断丝咆哮":"踏地冲锋",ready=state.spellCooldown<=0&&!paused,tip=paused?"战斗暂停，继续后可施法":ready?"流星术命中巨兽可打断":"流星术冷却中，准备承受冲击",content=`噬灯巨兽 · ${name}（${Math.ceil(boss.intent.remaining)} 秒）|${tip}`;ui.alert.classList.remove("hidden");ui.alert.classList.toggle("cooldown",!ready);if(content!==lastAlert){const [title,message]=content.split("|");ui.alert.innerHTML=`<strong>${title}</strong><span class="alert-tip">${message}</span>`;lastAlert=content}}
function phaseChanged(){if(phaseSeen===state.phase)return;phaseSeen=state.phase;syncUI();if(state.phase==="reward"){ui.reward.classList.remove("hidden");$("#rewardOptions").innerHTML=state.choices.map(choice=>`<button class="reward-option" data-upgrade="${choice.id}"><span class="rune">${choice.icon}</span><strong>${choice.name}</strong><small>${choice.description}</small></button>`).join("");say(`第 ${state.wave} 波守住了！选择一份月光祝福。`);tone(700,.18)}if(state.phase==="won"||state.phase==="lost"){const won=state.phase==="won";$("#endEyebrow").textContent=won?"破晓时分 · 守城成功":"夜色未散 · 城堡陷落";$("#endTitle").textContent=won?"蘑菇堡的灯还亮着":"今晚，月光先退了一步";$("#endDescription").textContent=won?"你和冒险者们守住了最后一盏灯。下一次，不妨试试另一种阵容。":"这次未能守住城门。调整部署位置、升级主力，再试一夜。";$("#endWave").textContent=state.wave;$("#endKills").textContent=state.kills;$("#endScore").textContent=state.score.toLocaleString("zh-CN");ui.end.classList.remove("hidden");if(state.score>best){best=state.score;ui.best.textContent=best.toLocaleString("zh-CN");try{localStorage.setItem(BEST_KEY,String(best))}catch{}}tone(won?800:210,.25);say(won?"守城成功！":"城堡陷落，再试一夜。")}}

function unitAt(x,y){return state.units.find(unit=>unit.x===x&&unit.y===y)}
function canvasCell(event){const rect=canvas.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width*canvas.width,y=(event.clientY-rect.top)/rect.height*canvas.height;return{x,y,cx:Math.floor(x/TILE),cy:Math.floor(y/TILE)}}
