ui.unitList.addEventListener("click",event=>{const button=event.target.closest("[data-type]");if(!button||button.disabled)return;selectedType=button.dataset.type;selectedUnit=null;targeting=false;say(`选择菌丝空位，放置${UNITS[selectedType].name}。`);tone(470);syncUI()});
ui.wave.onclick=()=>{if(startWave(state)){selectedUnit=null;targeting=false;paused=false;say(`第 ${state.wave} 波来袭！注意城堡生命。`);tone(350,.12);syncUI()}};
