document.addEventListener("keydown",event=>{if(!started||!ui.intro.classList.contains("hidden")||!ui.reward.classList.contains("hidden")||!ui.end.classList.contains("hidden"))return;if(event.target.closest("input,textarea,select"))return;if(["1","2","3"].includes(event.key)){const type=Object.keys(UNITS)[Number(event.key)-1];if(state.phase==="build"&&state.coins>=UNITS[type].cost){selectedType=type;selectedUnit=null;targeting=false;syncUI()}}else if(event.code==="Space"){event.preventDefault();ui.wave.click()}else if(event.key.toLowerCase()==="m"){ui.spell.click()}else if(event.key.toLowerCase()==="p"){ui.pause.click()}else if(event.key==="Escape"){targeting=false;selectedType=null;selectedUnit=null;syncUI()}});

